function makeBarChart(el, data, options) {{
  const width = el.clientWidth;
  const height = el.clientHeight;
  const margin = {{top: 16, right: 12, bottom: 34, left: 56}};
  const svg = d3.select(el).append('svg').attr('width', width).attr('height', height);
  const keys = Object.keys(data);
  const values = keys.map(k => ({{key:k, value:+data[k]}}));

  const x = d3.scaleLinear().domain([0, d3.max(values, d=>d.value)*1.08]).range([margin.left, width-margin.right]);
  const y = d3.scaleBand().domain(keys).range([margin.top, height-margin.bottom]).padding(0.22);

  svg.append('g')
    .attr('transform', `translate(0,${height-margin.bottom})`)
    .call(d3.axisBottom(x).ticks(5).tickSizeOuter(0))
    .call(g => g.selectAll('text').attr('fill', 'var(--muted)'))
    .call(g => g.selectAll('path,line').attr('stroke', 'var(--grid)'));

  svg.append('g')
    .attr('transform', `translate(${margin.left},0)`)
    .call(d3.axisLeft(y).tickSizeOuter(0))
    .call(g => g.selectAll('text').attr('fill', 'var(--muted)'))
    .call(g => g.selectAll('path,line').attr('stroke', 'var(--grid)'));

  svg.append('g')
    .selectAll('rect')
    .data(values)
    .join('rect')
    .attr('x', margin.left)
    .attr('y', d => y(d.key))
    .attr('height', y.bandwidth())
    .attr('width', d => x(d.value) - margin.left)
    .attr('fill', options.fill || 'var(--accent)')
    .attr('opacity', 0.9);

  svg.append('g')
    .selectAll('text.val')
    .data(values)
    .join('text')
    .attr('class','val')
    .attr('x', d => x(d.value) + 6)
    .attr('y', d => y(d.key) + y.bandwidth()/2 + 4)
    .attr('fill', 'var(--text)')
    .attr('font-size', 12)
    .text(d => options.labelFn ? options.labelFn(d) : d.value.toLocaleString());
}}

function makeVerticalBarChart(el, rows, options) {{
  const width = el.clientWidth;
  const height = el.clientHeight;
  const margin = {{top: 18, right: 12, bottom: 58, left: 54}};
  const svg = d3.select(el).append('svg').attr('width', width).attr('height', height);

  const x = d3.scaleBand().domain(rows.map(r=>r.x)).range([margin.left, width-margin.right]).padding(0.22);
  const y = d3.scaleLinear().domain([0, d3.max(rows, r=>r.y)*1.08]).nice().range([height-margin.bottom, margin.top]);

  svg.append('g')
    .attr('transform', `translate(0,${height-margin.bottom})`)
    .call(d3.axisBottom(x).tickSizeOuter(0))
    .call(g => g.selectAll('text').attr('fill','var(--muted)').attr('transform','rotate(-30)').style('text-anchor','end'))
    .call(g => g.selectAll('path,line').attr('stroke','var(--grid)'));

  svg.append('g')
    .attr('transform', `translate(${margin.left},0)`)
    .call(d3.axisLeft(y).ticks(5).tickSizeOuter(0))
    .call(g => g.selectAll('text').attr('fill','var(--muted)'))
    .call(g => g.selectAll('path,line').attr('stroke','var(--grid)'));

  svg.append('g')
    .selectAll('rect')
    .data(rows)
    .join('rect')
    .attr('x', d => x(d.x))
    .attr('y', d => y(d.y))
    .attr('width', x.bandwidth())
    .attr('height', d => y(0)-y(d.y))
    .attr('fill', options.fill || 'var(--accent2)')
    .attr('opacity', 0.9);
}}

function makeLaunchStacked(el, data) {{
  const width = el.clientWidth;
  const height = el.clientHeight;
  const margin = {{top: 20, right: 16, bottom: 34, left: 60}};
