  const x = d3.scaleLinear().domain(d3.extent(years)).range([margin.left, width-margin.right]);
  const y = d3.scaleLinear().domain([0, d3.max(data, d=>d.total)*1.12]).nice().range([height-margin.bottom, margin.top]);

  // grid
