function makeLaunchStacked(el, data) {{
  const width = el.clientWidth;
  const height = el.clientHeight;
  const margin = {{top: 20, right: 16, bottom: 34, left: 60}};
  const svg = d3.select(el).append('svg').attr('width', width).attr('height', height);

  const years = data.map(d=>d.year);
  const x = d3.scaleLinear().domain(d3.extent(years)).range([margin.left, width-margin.right]);
  const y = d3.scaleLinear().domain([0, d3.max(data, d=>d.total)*1.12]).nice().range([height-margin.bottom, margin.top]);

  // grid
  svg.append('g')
    .attr('transform', `translate(${margin.left},0)`)
    .call(d3.axisLeft(y).ticks(6).tickSize(-(width-margin.left-margin.right)).tickFormat(d3.format('~s')))
    .call(g => g.selectAll('text').attr('fill','var(--muted)'))
    .call(g => g.selectAll('line').attr('stroke','var(--grid)'))
    .call(g => g.selectAll('path').attr('stroke','var(--grid)'));

  svg.append('g')
    .attr('transform', `translate(0,${height-margin.bottom})`)
    .call(d3.axisBottom(x).ticks(10).tickFormat(d3.format('d')))
    .call(g => g.selectAll('text').attr('fill','var(--muted)'))
    .call(g => g.selectAll('path,line').attr('stroke','var(--grid)'));

  // area stacks
  const areaStar = d3.area()
    .x(d => x(d.year))
    .y0(d => y(0))
    .y1(d => y(d.starlink))
    .curve(d3.curveMonotoneX);

  const areaNon = d3.area()
    .x(d => x(d.year))
    .y0(d => y(d.starlink))
    .y1(d => y(d.total))
    .curve(d3.curveMonotoneX);

  svg.append('path').datum(data).attr('d', areaStar).attr('fill','var(--accent)').attr('opacity',0.85);
  svg.append('path').datum(data).attr('d', areaNon).attr('fill','var(--accent2)').attr('opacity',0.75);

  // total line
  const line = d3.line().x(d=>x(d.year)).y(d=>y(d.total)).curve(d3.curveMonotoneX);
  svg.append('path').datum(data).attr('d', line).attr('fill','none').attr('stroke','rgba(233,238,252,0.55)').attr('stroke-width',2);

  // annotations: 2020 and 2025
  const ann = [2020, 2025];
  ann.forEach(yr => {{
    const d = data.find(r=>r.year===yr);
    if(!d) return;
    svg.append('line').attr('x1', x(yr)).attr('x2', x(yr)).attr('y1', y(0)).attr('y2', y(d.total))
      .attr('stroke','rgba(251,191,36,0.55)').attr('stroke-dasharray','4,4');
    svg.append('text').attr('x', x(yr)+6).attr('y', y(d.total)-6).attr('fill','var(--warn)').attr('font-size',12)
      .text(`${yr}: ${d.total.toLocaleString()}`);
  }});
}}

