  labelFn: d => `${d.value.toLocaleString()} (${regimeShare[d.key].toFixed(2)}%)`
}});

// Constellation bar (top prefixes)
const constRows = Object.entries(constellationData).map(([k,v]) => ({{key:k, value:+v}}));
makeBarChart(document.getElementById('constellationBar'), Object.fromEntries(constRows.map(r=>[r.key,r.value])), {{
  fill: 'var(--accent)',
